  class ConfigEstructurarModelosNominaEntidad extends BaseConfigEstructurarModelosNominaEntidad
  {
    public static function estaReplicadoConceptosGeneralesNomina($idestructuramodelodomina,$idestructura)
    {
      $resul= Doctrine_Query::create()
        ->select('idestructuramodelodomina,idestructura')
        ->from('ConfigEstructurarModelosNominaEntidad')
        ->where('idestructuramodelodomina = ? and idestructura= ?',
          array($idestructuramodelodomina,$idestructura))
        ->fetchArray();

      return count($resul)>0;
    }
  }
